verification_commands.ac2:
set -u
W=.github/workflows/promote.yml
test -f "$W" || { echo "ac2 RED: $W missing"; exit 1; }
T=$(tr -d '\r' < "$W")
for bad in "^[[:space:]]*push:" "^[[:space:]]*pull_request:" "^[[:space:]]*schedule:" "^[[:space:]]*workflow_run:" "^[[:space:]]*repository_dispatch:" "^[[:space:]]*release:"; do
  if printf "%s\n" "$T" | grep -qE "$bad"; then
    echo "ac2 RED: promote.yml carries the trigger '$bad' - a manually gated deploy that can also fire automatically is the exact over-claim the CI/CD dimension punishes, and it would double-deploy alongside deploy.yml"; exit 1
  fi
done
printf "%s\n" "$T" | grep -qE "^[[:space:]]*workflow_dispatch:" || { echo "ac2 RED: no workflow_dispatch trigger line"; exit 1; }
echo "ac2 evidence: workflow_dispatch is the sole trigger"
printf "%s\n" "$T" | grep -qE "^[[:space:]]*environment:[[:space:]]*production[[:space:]]*$" || { echo "ac2 RED: no 'environment: production' line on the job - the required-reviewer gate is the human half of the third CI/CD point and the operator created that Environment for this purpose"; exit 1; }
printf "%s\n" "$T" | grep -qE "^[[:space:]]*permissions:[[:space:]]*$" && printf "%s\n" "$T" | grep -qE "^[[:space:]]*contents:[[:space:]]*read[[:space:]]*$" || { echo "ac2 RED: permissions: contents: read is not expressed as the workflow-level block the other three pipelines use"; exit 1; }
# the honesty clause: the file's own comments must not imply a second environment
printf "%s\n" "$T" | grep -qiE "staging|dev environment|development environment|second (render )?service|separate (environment|instance)" && { echo "ac2 RED: promote.yml's comments mention a staging/dev environment or a second service - there is ONE live Render service and the operator's instruction is explicit that environment separation does NOT exist while the human gate DOES"; exit 1; }
printf "%s\n" "$T" | grep -qiE "same live|same service|one service|single service|environment separation does not exist" || { echo "ac2 RED: the file never states the single-service truth in its own comments - a reviewer reading only promote.yml must not conclude a production tier sits behind a staging tier"; exit 1; }
printf "%s\n" "$T" | grep -qiE "repository Settings|not in git|required reviewer" || { echo "ac2 RED: the file does not disclose where the gate actually lives - the Environment is a repo-Settings artifact and the YAML is the only half a reader can see"; exit 1; }
# NEGATIVE CONTROL: the trigger leg must bite
NC=$(printf '%s\n' 'on:' '  push:' '    branches: [main]' '  workflow_dispatch:' 'permissions:' '  contents: read' | grep -cE "^[[:space:]]*push:")
[ "${NC:-0}" = "1" ] || { echo "ac2 RED: NEGATIVE CONTROL FAILED - the trigger detector did not flag a synthetic workflow that pushes to main, so the leg above is inert"; exit 1; }
echo "ac2 GREEN: GATE CONTRACT SOUND - workflow_dispatch is the only trigger (and the detector bites), environment: production is the human gate, permissions are least-privilege, and the file's own comments tell the truth about the single live service and the Settings-side gate"

verification_commands.ac3:
set -u
W=.github/workflows/promote.yml
D=.github/workflows/deploy.yml
test -f "$W" || { echo "ac3 RED: $W missing"; exit 1; }
test -f "$D" || { echo "ac3 RED: $D missing - the isomorphism has no reference"; exit 1; }
T=$(tr -d '\r' < "$W")
printf "%s\n" "$T" | grep -qE 'RENDER_HOOK: \$\{\{[[:space:]]*secrets[.]RENDER_DEPLOY_HOOK[[:space:]]*\}\}' || { echo "ac3 RED: the hook is not taken from secrets.RENDER_DEPLOY_HOOK - REQ-CICD-070 says the hook URL lives ONLY in that secret, and t119 adds no new secret"; exit 1; }
printf "%s\n" "$T" | grep -qE 'curl[[:space:]]+-fsS[[:space:]]+-X[[:space:]]+POST[[:space:]]+"\$RENDER_HOOK"' || { echo "ac3 RED: no curl -fsS -X POST \"\$RENDER_HOOK\" step - the deploy action itself is missing"; exit 1; }
printf "%s\n" "$T" | grep -qE '\-z "\$RENDER_HOOK"' || { echo "ac3 RED: the empty-secret guard is missing - deploy.yml fails loudly when the hook is unconfigured and a silent POST to an empty URL is a false green"; exit 1; }
printf "%s\n" "$T" | grep -qE 'RENDER_APP_URL|APP_HEALTH_URL: \$\{\{[[:space:]]*secrets[.]' || { echo "ac3 RED: the health URL is not sourced from a secret the way deploy.yml sources it - a hardcoded URL would also be a config drift the moment the service moves"; exit 1; }
printf "%s\n" "$T" | grep -qE 'for i in \$\(seq 1 30\)' || { echo "ac3 RED: the retry is not the bounded 'seq 1 30' loop - an unbounded retry hangs the runner and an absent retry means 'deployed' means 'curl fired'"; exit 1; }
printf "%s\n" "$T" | grep -qE 'sleep 10' || { echo "ac3 RED: no sleep 10 between attempts - the backoff is part of the pinned contract"; exit 1; }
printf "%s\n" "$T" | grep -qE 'exit 1' || { echo "ac3 RED: the job does not fail when the health endpoint never turns ok (REQ-CICD-060)"; exit 1; }
# isomorphism, measured rather than asserted: the same three constructs must appear in deploy.yml
for pat in 'for i in \$\(seq 1 30\)' 'sleep 10' 'curl[[:space:]]+-fsS[[:space:]]+-X[[:space:]]+POST'; do
  tr -d '\r' < "$D" | grep -qE "$pat" || { echo "ac3 RED: reference drift - deploy.yml no longer contains '$pat', so 'isomorphic to deploy.yml' is no longer a checkable claim; re-measure the reference and update this card rather than shipping a fiction"; exit 1; }
done
for s in RENDER_HOOK APP_HEALTH_URL; do
  printf "%s\n" "$T" | grep -qE "\"\$$s\"" || { echo "ac3 RED: \$$s is never dereferenced - the env binding is decorative"; exit 1; }
done
# no new secret name may appear
NEW=""
for s in $(printf "%s\n" "$T" | grep -oE "secrets[.][A-Z0-9_]+" | sed 's/secrets[.]//' | sort -u); do
  case "$s" in RENDER_DEPLOY_HOOK|RENDER_APP_URL) : ;; *) NEW="$NEW $s" ;; esac
done
[ -z "${NEW// /}" ] || { echo "ac3 RED: promote.yml references secret names the pipeline does not already have:$NEW - the brief forbids new secrets, and an undeclared secret silently expands to an empty string, which is how a deploy job goes green while doing nothing"; exit 1; }
printf "%s\n" "$T" | grep -qE "^[[:space:]]*secrets:[[:space:]]*$" && { echo "ac3 RED: promote.yml declares its own secrets: block - the operator's rule is no new secrets and no redeclaration"; exit 1; }
echo "ac3 GREEN: DEPLOY CONTRACT ISOMORPHIC - hook from RENDER_DEPLOY_HOOK only, empty-secret guard present, health URL from the existing secret, the bounded 30x10s retry and the fail-closed exit reproduced from deploy.yml, and zero new secret names"

verification_commands.ac5:
set -u
test -f docs/state/merge_test_index.json || { echo "ac5 RED: docs/state/merge_test_index.json missing"; exit 1; }
command -v python3 >/dev/null || { echo "ac5 RED: python3 missing"; exit 1; }
python3 - <<'PYEOF' || exit 1
import hashlib, json, os, sys
A = "docs/state/outputs/t119_definer_gate_amendment.json"
if not os.path.exists(A):
    sys.stderr.write("ac5 RED: %s missing - a fourth workflow file moves eight stored surfaces, and a card that moves them silently is how a green merge produces a red suite\n" % A)
    raise SystemExit(1)
rec = json.load(open(A, encoding="utf-8"))
if rec.get("card") != "t119":
    sys.stderr.write("ac5 RED: the record does not belong to card t119\n"); raise SystemExit(1)
if rec.get("status") not in ("proposed", "ratified"):
    sys.stderr.write("ac5 RED: the record must be labelled proposed (ratified once the orchestrator applies it); a definer may not self-apply\n"); raise SystemExit(1)
if not str(rec.get("applied_by", "")).startswith("orchestrator") or rec.get("card_writes_index_bytes") is not False:
    sys.stderr.write("ac5 RED: the record must declare applied_by=orchestrator and card_writes_index_bytes=false - the index is orchestrator-owned and t119 writes no index byte\n"); raise SystemExit(1)
if rec.get("no_leg_deleted") is not True or rec.get("verifier_thresholds_touched") is not False:
    sys.stderr.write("ac5 RED: the record must declare no_leg_deleted=true and verifier_thresholds_touched=false - the amendment re-premises expectations, it never deletes a leg or moves a threshold\n"); raise SystemExit(1)
am = rec.get("amendments", [])
legs = sorted(int(a["index"]) for a in am)
want = [131, 143, 155, 162, 167, 177, 191]
if legs != want:
    sys.stderr.write("ac5 RED: the record must amend exactly legs %s, found %s (131 asserts no non-ci/e2e/deploy file exists; 162/167/177/191 assert the exact four-name listing; 143/155 pin the WORKFLOWS and WORKFLOW_TRIGGERS report lines verbatim; 227 belongs to t111's record)\n" % (want, legs)); raise SystemExit(1)
idx = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
def esha(e):
    return hashlib.sha256(json.dumps(e, separators=(",", ":")).encode("utf-8")).hexdigest()
def apply_regions(src, pairs, direction):
    out = src
    for r in pairs:
        needle = r["from"] if direction == "forward" else r["to"]
        repl = r["to"] if direction == "forward" else r["from"]
        if out.count(needle) != 1:
            sys.stderr.write("ac5 RED: a replaced_region %s text is not unique in the shipped tests[%d] command - the record does not describe the shipped bytes\n" % ("from" if direction == "forward" else "to", int(r.get("leg", -1)))); raise SystemExit(1)
        out = out.replace(needle, repl, 1)
    return out
states = []
for a in am:
    i = int(a["index"])
    t = idx[i]
    cmd = t["command"]
    csha = hashlib.sha256(cmd.encode("utf-8")).hexdigest()
    regs = a.get("replaced_regions", [])
    if not regs:
        sys.stderr.write("ac5 RED: leg %d carries no replaced_regions - the edit must be reconstructible byte-for-byte\n" % i); raise SystemExit(1)
    if csha == a["old_command_sha256"]:
        if esha(t) != a.get("entry_sha_before"):
            sys.stderr.write("ac5 RED: leg %d still holds the OLD command but the entry sha moved - the entry was edited outside the record\n" % i); raise SystemExit(1)
        built = apply_regions(cmd, regs, "forward")
        if hashlib.sha256(built.encode("utf-8")).hexdigest() != a.get("new_command_sha256"):
            sys.stderr.write("ac5 RED: leg %d forward application of replaced_regions does not reproduce new_command_sha256\n" % i); raise SystemExit(1)
        if apply_regions(built, regs, "reverse") != cmd:
            sys.stderr.write("ac5 RED: leg %d is not lossless - reversing the regions does not reproduce the shipped command\n" % i); raise SystemExit(1)
        states.append("pre")
    elif csha == a["new_command_sha256"]:
        if esha(t) != a.get("entry_sha_after"):
            sys.stderr.write("ac5 RED: leg %d holds the SETTLED command but not the recorded entry_sha_after - the settled entry drifted from the record\n" % i); raise SystemExit(1)
        if apply_regions(cmd, regs, "reverse") == cmd:
            sys.stderr.write("ac5 RED: leg %d reverse application changed nothing - the record does not describe the shipped bytes\n" % i); raise SystemExit(1)
        states.append("post")
    else:
        sys.stderr.write("ac5 RED: leg %d command sha %s matches NEITHER old_command_sha256 nor new_command_sha256 - the index drifted under the record\n" % (i, csha[:16])); raise SystemExit(1)
    if "workflows" not in cmd and "WORKFLOWS" not in cmd:
        sys.stderr.write("ac5 RED: leg %d does not touch .github/workflows at all - the record is guessing\n" % i); raise SystemExit(1)
if len(set(states)) != 1:
    sys.stderr.write("ac5 RED: the seven legs are in a MIXED pre/post state (%s) - the merge window must apply the whole record in one window\n" % states); raise SystemExit(1)
if 227 in legs:
    sys.stderr.write("ac5 RED: tests[227] must not be amended here - it is settled by t111_definer_gate_amendment.json; two records editing one entry is how byte-proofs rot\n"); raise SystemExit(1)
g = rec.get("generator_constant")
if not isinstance(g, dict) or g.get("path") != "backend/scripts/infra_verification.py" or g.get("t119_writes_generator") is not True:
    sys.stderr.write("ac5 RED: the record must state that the EXPECTED_WORKFLOWS constant in backend/scripts/infra_verification.py is t119 OWNED surface (ruling WAL 1268 R1)\n"); raise SystemExit(1)
if g.get("before_literal") != 'EXPECTED_WORKFLOWS = ("ci", "e2e", "deploy")' or g.get("after_literal") != 'EXPECTED_WORKFLOWS = ("ci", "e2e", "deploy", "promote")':
    sys.stderr.write("ac5 RED: the record must pin the generator before/after literals byte-exactly - the tuple line is the whole product delta\n"); raise SystemExit(1)
if "141" not in set(str(x) for x in g.get("blocking_legs", [])):
    sys.stderr.write("ac5 RED: the record must name leg 141 as the leg the constant gates (it EXECUTES the generator and requires exit 0 plus ALL_CHECKS_PASS >= 20)\n"); raise SystemExit(1)
ap = rec.get("generator_anchor_pin")
if not isinstance(ap, dict) or ap.get("surface") != "backend/scripts/docs_verification.py INDEX_ANCHORS[131]":
    sys.stderr.write("ac5 RED: the record must price the INDEX_ANCHORS[131] rotation - amending leg 131 without rotating that byte-pinned entry sha turns docs_verification.py itself RED\n"); raise SystemExit(1)
if len(ap.get("old_entry_sha", "")) != 64 or len(ap.get("new_entry_sha", "")) != 64 or ap["old_entry_sha"] == ap["new_entry_sha"]:
    sys.stderr.write("ac5 RED: the anchor pin must carry two distinct 64-hex entry shas\n"); raise SystemExit(1)
nc = rec.get("negative_control_matrix", [])
if len(nc) < 5:
    sys.stderr.write("ac5 RED: the record needs at least five negative-control legs, found %d\n" % len(nc)); raise SystemExit(1)
bad = [x.get("case") for x in nc if x.get("measured_rc") != x.get("expected_rc")]
if bad:
    sys.stderr.write("ac5 RED: negative-control legs not as expected: %s\n" % bad); raise SystemExit(1)
sys.stdout.write("ac5 GREEN: R2 AMENDMENT RECORD SOUND - %s prices legs %s (each verified against the shipped index in the %s state, every region lossless in both directions), excludes tests[227], records the EXPECTED_WORKFLOWS before/after literals with leg 141 as the gated leg, prices the INDEX_ANCHORS[131] rotation, and carries %d as-expected negative controls\n" % (A, ",".join(str(x) for x in legs), ("pre-settlement" if states[0] == "pre" else "post-settlement"), len(nc)))
PYEOF
